def with_extension(name, ext="md"):
    idx = name.rfind('.')
    if idx > 0:
        return name[:idx] + "." + ext
    elif idx == 0:
        return name + "." + ext
    else:
        return name + "." + ext

assert with_extension("foo") == "foo.md"
assert with_extension("foo.bar") == "foo.md"
assert with_extension(".hidden") == ".hidden.md"
assert with_extension(".hidden.foo") == ".hidden.md"
assert with_extension("a.b.c") == "a.b.md"
